pub fn facet_by_customer_as(self, facet_name: impl Into<String>, request: impl Into<QuerySelection>) -> Self {
        self.facet_by_customer_as_with_options(facet_name, request, true)
    }

pub fn facet_by_customer_as_with_options(
        mut self,
        facet_name: impl Into<String>,
        request: impl Into<QuerySelection>,
        include_all_facets: bool,
    ) -> Self {
        self.query_options.facets.push(FacetRequest::new(
            facet_name,
            "customer",
            request,
            include_all_facets,
        ));
        self
    }

pub fn group_by_customer_with(mut self, request: impl Into<QuerySelection>) -> Self {
        self.query = self.query.group_by("customer_id");
        self.query_options.object_group_bys.push(ObjectGroupBy::new(
            "customer",
            "customer_id",
            request,
        ));
        self
    }

pub fn group_by_customer_with_details_from(self, request: impl Into<QuerySelection>) -> Self {
        self.group_by_customer_with(request)
    }

pub fn count_orders_with(mut self, alias: impl Into<String>, request: impl Into<QuerySelection>) -> Self {
        let selection = request.into();
        self.query_options.relation_aggregates.push(RelationAggregate::new(
            "orders",
            alias,
            selection,
            true,
        ));
        self
    }

pub fn stats_from_orders(self, request: impl Into<QuerySelection>) -> Self {
        self.stats_from_orders_as("refinements", request)
    }

pub fn stats_from_orders_as(mut self, alias: impl Into<String>, request: impl Into<QuerySelection>) -> Self {
        let selection = request.into();
        self.query_options.relation_aggregates.push(RelationAggregate::new(
            "orders",
            alias,
            selection,
            false,
        ));
        self
    }

pub fn group_by_orders_with_details(self, request: impl Into<QuerySelection>) -> Self {
        self.stats_from_orders(request)
    }
